import styles from './ArrayVisual.module.css';

const ArrayVisual = ({ array, hasTitle }) => {
  return (
    <div className={styles.arrayContainer}>
      {hasTitle && (<h4>Array Representation</h4>)}
      <ArrayTable array={array} />
    </div>
  );
};

const ArrayTable = ({ array }) => {
  return (
    <div className={styles.arrayWrapper}>
        {/* index row */}
        <div className={styles.arrayHeader}>
          <div className={styles.headerCell}>Index</div>
          {array.map((_, index) => (
            <div key={index} className={styles.headerCell}>
              {index}
            </div>
          ))}
        </div>

        {/* value row */}
        <div className={styles.arrayRow}>
          <div className={styles.rowLabel}>Value</div>
          {array.map((value, index) => (
            <div 
              key={index} 
              className={styles.arrayCell}
            >
              "{value}"
            </div>
          ))}
        </div>
    </div>
  );
}

export default ArrayVisual;