import React from 'react';
import styles from './Slide.module.css';
import TreeDiagram from '../../common/TreeDiagram';
import DaryTreeDiagram from '../../common/DaryTreeDiagram';
import HeapVisualization from '../../common/HeapVisualization';
import CodeBlock from '../../common/CodeBlock';
import ArrayVisual from '../../common/ArrayVisual';

const Slide = ({ slide, diagrams, scrollRef }) => {
  const renderSection = (section, index) => {
    switch (section.type) {
      case 'text':
        return <p key={index} className={styles.text}>{section.content}</p>;
      
      case 'visual_comparison':
        return (
          <div key={index} className={styles.visualComparison}>
            <h3>{section.title}</h3>
            <div className={styles.comparisonContainer}>
              <ArrayVisual array={diagrams?.module1.array} hasTitle={true} />
              <TreeDiagram array={diagrams?.module1?.array || ["5", "3", "8", "1", "4", "6"]} />
            </div>
            <p>{section.content}</p>
          </div>
        );
      
      case 'formula':
        return (
          <div key={index} className={styles.formulaBox}>
            <h3>{section.title}</h3>
            <div className={styles.formulas}>
              {section.formulas.map((formula, i) => (
                <div key={i} className={styles.formulaItem}>
                  {formula}
                </div>
              ))}
            </div>
            <p className={styles.example}>{section.example}</p>
          </div>
        );
      
      case 'dary_visualization':
        return (
          <div key={index} className={styles.visualBox}>
            <h3>{section.title}</h3>
            <DaryTreeDiagram 
              d={section.d || 3}
              array={section.array || diagrams?.module5?.ternaryTree?.array || ["R", "A", "B", "C", "D", "E", "F"]}
            />
            {section.content && <p className={styles.visualDescription}>{section.content}</p>}
          </div>
        );
      
      case 'heap_visualization':
        return (
          <div key={index} className={styles.visualBox}>
            <h3>{section.title}</h3>
            <HeapVisualization 
              heapArray={section.heapArray || diagrams?.module6?.heapArray || []}
              operations={section.operations || diagrams?.module6?.heapOperations || []}
              interactive={section.interactive || false}
            />
            {section.content && <p className={styles.visualDescription}>{section.content}</p>}
          </div>
        );
      
      case 'practice':
        return (
          <div key={index} className={styles.practiceBox}>
            <h4>Quick Practice</h4>
            <p className={styles.question}>{section.question}</p>
            <div className={styles.options}>
              {section.options.map((option, i) => (
                <div key={i} className={styles.option}>
                  {String.fromCharCode(65 + i)}) {option}
                </div>
              ))}
            </div>
            <div className={styles.explanation}>
              <strong>Answer: </strong>
              {section.explanation}
            </div>
          </div>
        );
      
      case 'code':
        return (
          <div key={index}>
            {section.title && <h3>{section.title}</h3>}
            <CodeBlock 
              code={section.code} 
              language={section.language || 'python'}
            />
          </div>
        );
      
      case 'comparison':
        return (
          <div key={index} className={styles.comparisonBox}>
            <h3>{section.title}</h3>
            <div className={styles.comparisonGood}>
              <strong>✓ Good Example:</strong> {section.good}
            </div>
            <div className={styles.comparisonBad}>
              <strong>✗ Bad Example:</strong> {section.bad}
            </div>
          </div>
        );
      
      case 'definition':
        return (
          <div key={index} className={styles.definitionBox}>
            <h4>{section.term}</h4>
            <p className={styles.definition}>{section.definition}</p>
          </div>
        );
      
      default:
        return null;
    }
  };

  return (
    <div className={styles.slide} ref={scrollRef}>
      <h2 className={styles.slideTitle}>{slide.title}</h2>
      <div className={styles.slideContent}>
        {slide.sections.map((section, index) => renderSection(section, index))}
      </div>
    </div>
  );
};

export default Slide;