import React from 'react';
import styles from './PlatformHeader.module.css';

const PlatformHeader = () => {
  return (
    <header className={styles.platformHeader}>
      <div className={styles.headerLeft}>
        <div className={styles.logo}>
          <span className={styles.logoIcon}>🌳</span>
          <span className={styles.logoText}>CS Learning Hub</span>
        </div>
        <nav className={styles.mainNav}>
          <a href="#" className={styles.navLink}>Home</a>
          <a href="#" className={styles.navLink}>Courses</a>
          <a href="#" className={`${styles.navLink} ${styles.active}`}>Learn</a>
          <a href="#" className={styles.navLink}>Practice</a>
          <a href="#" className={styles.navLink}>Community</a>
        </nav>
      </div>
      
      <div className={styles.headerRight}>
        <div className={styles.searchBar}>
          <input 
            type="text" 
            placeholder="Search courses, topics..." 
            className={styles.searchInput}
          />
          <button className={styles.searchButton}>🔍</button>
        </div>
        
        <div className={styles.userSection}>
          <button className={styles.notificationButton}>
            <span className={styles.notificationIcon}>🔔</span>
            <span className={styles.notificationBadge}>3</span>
          </button>
          
          <div className={styles.userMenu}>
            <div className={styles.userAvatar}>XX</div>
            <span className={styles.userName}>You</span>
            <span className={styles.dropdownArrow}>▾</span>
          </div>
        </div>
      </div>
    </header>
  );
};

export default PlatformHeader;