import Tree from '../tree-visuals/Tree';
import ArrayVisual from './ArrayVisual';
import { buildHeapTree } from '../tree-visuals/treeBuilders';
import styles from './HeapVisualization.module.css';

const HeapVisualization = ({ heapArray = [], operations = [] }) => {
  const tree = buildHeapTree(heapArray);
  const minValue = heapArray.length > 0 ? Math.min(...heapArray) : null;

  return (
    <div className={styles.heapContainer}>
      
      <h4>Binary Heap Example</h4>
      
      <div className={styles.treeSection}>
        <Tree 
          treeData={tree}
          width={400}
          height={220}
          verticalSpacing={60}
          horizontalSpacing={100}
        />
        
        {minValue !== null && (
          <div className={styles.minIndicator}>
            Minimum: {minValue} (at root)
          </div>
        )}
      </div>

      <div className={styles.arraySection}>
        <ArrayVisual array={heapArray} hasTitle={false} />
      </div>

      {/* walkthrough of operations */}
      {operations && operations.length > 0 && (
        <div className={styles.operationsSection}>
          {operations.map((operation, index) => (
            <div key={index} className={styles.operationItem}>
              {operation}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default HeapVisualization;