import React from 'react';
import styles from './Navigation.module.css';

const Navigation = ({ currentModule, setCurrentModule, totalModules = 6 }) => {
  const modules = [
    { id: 1, title: "Arrays and Their Structure", duration: "2 min" },
    { id: 2, title: "Properties of Implicit Trees", duration: "2 min" },
    { id: 3, title: "Memory Efficiency", duration: "2 min" },
    { id: 4, title: "Advanced Operations", duration: "2 min" },
    { id: 5, title: "Generalizing to d-ary Trees", duration: "2 min" },
    { id: 6, title: "Binary Heaps Application", duration: "2 min" }
  ];

  return (
    <nav className={styles.navigation}>
      <div className={styles.navHeader}>
        <h3 className={styles.navTitle}>Course Content</h3>
        <div className={styles.moduleCount}>
          {totalModules} modules • 10m
        </div>
      </div>
      
      <div className={styles.moduleList}>
        {modules.map((module, index) => (
          <div 
            key={module.id}
            className={`${styles.moduleItem} ${currentModule === module.id ? styles.active : ''}`}
            onClick={() => setCurrentModule(module.id)}
          >
            <div className={styles.moduleIndicator}>
              <div className={styles.indicatorCircle}>
                {currentModule > module.id ? (
                  <span className={styles.completedIcon}>✓</span>
                ) : (
                  <span className={styles.moduleNumber}>{module.id}</span>
                )}
              </div>
              {index < modules.length - 1 && (
                <div className={`${styles.connectorLine} ${currentModule > module.id ? styles.completedLine : ''}`} />
              )}
            </div>
            
            <div className={styles.moduleContent}>
              <div className={styles.moduleHeader}>
                <span className={styles.moduleTitle}>Module {module.id}</span>
                <span className={styles.moduleDuration}>{module.duration}</span>
              </div>
              <p className={styles.moduleDescription}>{module.title}</p>
              
              {currentModule === module.id && (
                <div className={styles.currentModuleIndicator}>
                  <span className={styles.currentLabel}>Currently viewing</span>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>
      
      <div className={styles.navFooter}>
        <div className={styles.completionStats}>
          <div className={styles.statItem}>
            <span className={styles.statValue}>{Math.round((currentModule / totalModules) * 100)}%</span>
            <span className={styles.statLabel}>Complete</span>
          </div>
          <div className={styles.statItem}>
            <span className={styles.statValue}>{currentModule}</span>
            <span className={styles.statLabel}>Modules done</span>
          </div>
          <div className={styles.statItem}>
            <span className={styles.statValue}>{totalModules - currentModule}</span>
            <span className={styles.statLabel}>Remaining</span>
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navigation;