import React from 'react';
import styles from './ModuleModal.module.css';

const ModuleModal = ({ 
  modules, 
  currentModuleId, 
  onSelectModule, 
  onClose 
}) => {
  return (
    <div className={styles.modalOverlay}>
      <div className={styles.modal}>
        <div className={styles.modalHeader}>
          <h2 className={styles.modalTitle}>Select Module</h2>
          <button className={styles.closeButton} onClick={onClose}>
            ✕
          </button>
        </div>
        
        <div className={styles.modalContent}>
          <div className={styles.moduleGrid}>
            {modules.map(module => (
              <div 
                key={module.id}
                className={`${styles.moduleCard} ${currentModuleId === module.id ? styles.active : ''}`}
                onClick={() => onSelectModule(module.id)}
              >
                <div className={styles.moduleNumber}>
                  {module.id}
                </div>
                <div className={styles.moduleInfo}>
                  <h3 className={styles.moduleTitle}>Module {module.id}</h3>
                  <p className={styles.moduleDescription}>{module.title}</p>
                  <div className={styles.moduleMeta}>
                    <span className={styles.slideCount}>{module.slides.length} slides</span>
                    <span className={styles.completed}>
                      {currentModuleId > module.id ? '✓ Completed' : ''}
                    </span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
        
        <div className={styles.modalFooter}>
          <button className={styles.continueButton} onClick={onClose}>
            Continue Learning
          </button>
        </div>
      </div>
    </div>
  );
};

export default ModuleModal;