// convert arr to bin tree structure
export const buildBinaryTree = (array) => {
  if (!array || array.length === 0) return null;
  
  const nodes = array.map((value, index) => ({
    value: String(value),
    index: index,
    children: []
  }));
  
  // connect edges btwn parent & child
  for (let i = 0; i < nodes.length; i++) {
    const leftIndex = 2 * i + 1;
    const rightIndex = 2 * i + 2;
    
    if (leftIndex < nodes.length) {
      nodes[i].children.push(nodes[leftIndex]);
    }
    if (rightIndex < nodes.length) {
      nodes[i].children.push(nodes[rightIndex]);
    }
  }
  
  return nodes[0];
};

// convert array to d-ary tree structure
export const buildDaryTree = (array, d) => {
  if (!array || array.length === 0) return null;
  
  const nodes = array.map((value, index) => ({
    value: String(value),
    index: index,
    children: []
  }));
  
  // connect edges btwn parent & child
  for (let i = 0; i < nodes.length; i++) {
    for (let k = 0; k < d; k++) {
      const childIndex = d * i + k + 1;
      if (childIndex < nodes.length) {
        nodes[i].children.push(nodes[childIndex]);
      }
    }
  }
  
  return nodes[0];
};

export const buildHeapTree = (heapArray) => {
  return buildBinaryTree(heapArray); // heap = bin tree
};

// help calculate spacing for different tree types
export const getSpacingFunction = (treeType, d = 2) => {
  switch (treeType) {
    case 'binary':
      return (childCount, level, baseSpacing) => {
        if (childCount === 0) return 0;
        const spacing = baseSpacing / (level * 0.7 + 1);
        return childCount * spacing;
      };
    
    case 'dary':
      return (childCount, level, baseSpacing) => {
        if (childCount === 0) return 0;
        const adjustedBase = d === 2 ? 100 : d === 3 ? 80 : 60;
        const spacing = adjustedBase / (level * 0.6 + 1);
        return childCount * spacing;
      };
    
    case 'heap':
      return (childCount, level, baseSpacing) => {
        if (childCount === 0) return 0;
        const spacing = baseSpacing / (level * 0.7 + 1);
        return childCount * spacing;
      };
    
    default:
      return (childCount, level, baseSpacing) => childCount * (baseSpacing / (level + 1));
  }
};