import { useState, useEffect, useRef } from 'react';
import { modules, diagrams } from '../data/modules';
import ContentModule from '../components/common/ContentModule';
import Layout from '../components/designs/Design4/Layout';
import styles from './Design4.module.css';

const Design4 = () => {
  const [currentModule, setCurrentModule] = useState(1); // start with module 1 in progress
  const contentRef = useRef(null);

  const currentModuleData = modules.find(module => module.id === currentModule);
  
  let modulesInfo = [
    { id: 1, title: "Understanding Arrays and Their Structure", status: "in-progress" },
    { id: 2, title: "Properties and Advantages of Implicit Trees", status: "upcoming" },
    { id: 3, title: "Memory Efficiency and Performance Analysis", status: "upcoming" },
    { id: 4, title: "Advanced Operations and Analysis", status: "upcoming" },
    { id: 5, title: "Generalizing to d-ary Trees", status: "upcoming" },
    { id: 6, title: "Practical Application: Binary Heaps", status: "upcoming" }
  ];

  const handleStatusUpdates = () => {
    for(let i=0; i<modulesInfo.length; i++) {
      if(modulesInfo[i].id < currentModule) modulesInfo[i].status = "completed";
      else if(modulesInfo[i].id == currentModule) modulesInfo[i].status = "in-progress";
      else modulesInfo[i].status = "upcoming";
    }
  }

  // scroll to top & update status when module changes
  useEffect(() => {
    if (contentRef.current) {
      contentRef.current.scrollTop = 0;
    }
    handleStatusUpdates();
  }, [currentModule]);

  const handleNextModule = () => {
    if (currentModule < modules.length) {
      setCurrentModule(prev => prev + 1);
    }
  };

  const handlePreviousModule = () => {
    if (currentModule > 1) {
      setCurrentModule(prev => prev - 1);
    }
  };

  return (
    <div className={styles.design4Container}>
      <Layout 
        currentModule={currentModule}
        setCurrentModule={setCurrentModule}
        modules={modulesInfo}
        totalModules={modules.length}
        onNext={handleNextModule}
        onPrevious={handlePreviousModule}
      >
        <div className={styles.modalContentWrapper} ref={contentRef}>
          {currentModuleData && (
            <ContentModule 
              moduleData={currentModuleData} 
              diagrams={diagrams}
            />
          )}
        </div>
      </Layout>
    </div>
  );
};

export default Design4;