import React from 'react';
import styles from './ContentArea.module.css';

const ContentArea = ({ children, currentModule, totalModules, onNext, onPrevious }) => {
  return (
    <main className={styles.contentArea}>
      
      <div className={styles.contentHeader}>
        <div className={styles.breadcrumb}>
          <a href="#" className={styles.breadcrumbLink}>Home</a>
          <span className={styles.breadcrumbSeparator}>/</span>
          <a href="#" className={styles.breadcrumbLink}>Courses</a>
          <span className={styles.breadcrumbSeparator}>/</span>
          <a href="#" className={styles.breadcrumbLink}>Data Structures</a>
          <span className={styles.breadcrumbSeparator}>/</span>
          <span className={styles.breadcrumbCurrent}>Implicit Trees</span>
        </div>
      </div>
      
      <div className={styles.contentWrapper}>
        {children}
      </div>
      
      <div className={styles.contentFooter}>
        <div className={styles.navigationButtons}>
          <button 
            className={`${styles.navButton} ${styles.prevButton}`}
            onClick={onPrevious}
            disabled={currentModule === 1}
          >
            <span className={styles.buttonIcon}>←</span>
            Previous Module
          </button>
          
          <div className={styles.moduleProgress}>
            <span className={styles.progressText}>
              Module {currentModule} of {totalModules}
            </span>
            <div className={styles.progressDots}>
              {Array.from({ length: totalModules }).map((_, i) => (
                <div 
                  key={i}
                  className={`${styles.progressDot} ${i + 1 <= currentModule ? styles.active : ''}`}
                />
              ))}
            </div>
          </div>
          
          <button 
            className={`${styles.navButton} ${styles.nextButton}`}
            onClick={onNext}
            disabled={currentModule === totalModules}
          >
            Next Module
            <span className={styles.buttonIcon}>→</span>
          </button>
        </div>
      </div>
    </main>
  );
};

export default ContentArea;