import Tree from '../tree-visuals/Tree';
import ArrayVisual from './ArrayVisual';
import { buildDaryTree } from '../tree-visuals/treeBuilders';
import styles from './DaryTreeDiagram.module.css';

const DaryTreeDiagram = ({ d = 3, array = [] }) => {
  const tree = buildDaryTree(array, d);
  
  // to prevent overlap (hopefully)
  const getSimpleSpacing = (childCount, level) => {
    const baseSpacing = 80;
    return childCount * (baseSpacing / (level * 0.5 + 1));
  };

  return (
    <div className={styles.daryContainer}>
      <h4>{d}-ary Tree Example</h4>
      
      <div className={styles.diagramWrapper}>
        <Tree 
          treeData={tree}
          width={500}
          height={250}
          verticalSpacing={60}
          horizontalSpacing={80}
          getChildSpacing={getSimpleSpacing}
        />
      </div>
      
      <div className={styles.arraySection}>
        <ArrayVisual array={array} hasTitle={false} />
      </div>
    </div>
  );
};

export default DaryTreeDiagram;