import React, { useState, useEffect, useRef } from 'react';
import { modules, diagrams } from '../data/modules';
import ContentModule from '../components/common/ContentModule';
import Layout from '../components/designs/Design2/Layout';
import styles from './Design2.module.css';

const Design2 = () => {
  const [currentModule, setCurrentModule] = useState(1);
  const contentRef = useRef(null);

  const currentModuleData = modules.find(module => module.id === currentModule);

  // scroll to top when module changes
  useEffect(() => {
    if (contentRef.current) {
      contentRef.current.scrollTop = 0;
    }
  }, [currentModule]);

  const handleNextModule = () => {
    if (currentModule < modules.length) {
      setCurrentModule(prev => prev + 1);
    }
  };

  const handlePreviousModule = () => {
    if (currentModule > 1) {
      setCurrentModule(prev => prev - 1);
    }
  };

  return (
    <div className={styles.design2Container}>
      <Layout 
        currentModule={currentModule}
        setCurrentModule={setCurrentModule}
        totalModules={modules.length}
        onNext={handleNextModule}
        onPrevious={handlePreviousModule}
      >
        <div className={styles.moduleContent} ref={contentRef}>
          {currentModuleData && (
            <ContentModule 
              moduleData={currentModuleData} 
              diagrams={diagrams}
            />
          )}
        </div>
      </Layout>
    </div>
  );
};

export default Design2;