import styles from './Navigation.module.css';

const Navigation = ({ currentModule, setCurrentModule, modules, totalModules = 6 }) => {

  const getStatusLabel = (status) => {
    switch(status) {
      case 'completed': return '✓ Completed';
      case 'in-progress': return '▶ In Progress';
      default: return '○ Upcoming';
    }
  };

  const getStatusClass = (status) => {
    switch(status) {
      case 'completed': return styles.completed;
      case 'in-progress': return styles.inProgress;
      default: return styles.upcoming;
    }
  };

  return (
    <div className={styles.navigation}>
      <div className={styles.pageHeader}>
        <h1 className={styles.courseTitle}>Implicit Trees Course</h1>
        <p className={styles.courseDescription}>
          Learn how arrays can represent tree structures through mathematical relationships.
          Complete all modules to finish the course.
        </p>
      </div>

      <div className={styles.progressOverview}>
        <div className={styles.progressStats}>
          <div className={styles.statItem}>
            <span className={styles.statValue}>{Math.round((currentModule / totalModules) * 100)}%</span>
            <span className={styles.statLabel}>Overall Progress</span>
          </div>
          <div className={styles.statItem}>
            <span className={styles.statValue}>{currentModule - 1}</span>
            <span className={styles.statLabel}>Modules Completed</span>
          </div>
          <div className={styles.statItem}>
            <span className={styles.statValue}>{totalModules - currentModule}</span>
            <span className={styles.statLabel}>Modules Remaining</span>
          </div>
        </div>
        
        <div className={styles.progressBar}>
          <div 
            className={styles.progressFill} 
            style={{ width: `${((currentModule) / totalModules) * 100}%` }}
          />
        </div>
      </div>

      <div className={styles.modulesGrid}>
        <h2 className={styles.sectionTitle}>Course Modules</h2>
        <div className={styles.modulesList}>
          {modules.map(module => (
            <div 
              key={module.id}
              className={`${styles.moduleCard} ${module.id === currentModule ? styles.currentModule : ''}`}
              onClick={() => setCurrentModule(module.id)}
            >
              <div className={styles.moduleHeader}>
                <span className={styles.moduleNumber}>Module {module.id}</span>
                <span className={`${styles.moduleStatus} ${getStatusClass(module.status)}`}>
                  {getStatusLabel(module.status)}
                </span>
              </div>
              <h3 className={styles.moduleTitle}>{module.title}</h3>
              <div className={styles.moduleFooter}>
                <span className={styles.moduleDuration}>~2 minutes</span>
                <button className={styles.moduleButton}>
                  {module.id === currentModule ? 'Continue →' : 
                   module.status === 'completed' ? 'Review' : 'Start'}
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className={styles.courseInfo}>
        <h3 className={styles.infoTitle}>Course Information</h3>
        <div className={styles.infoGrid}>
          <div className={styles.infoItem}>
            <span className={styles.infoLabel}>Difficulty:</span>
            <span className={styles.infoValue}>Intermediate</span>
          </div>
          <div className={styles.infoItem}>
            <span className={styles.infoLabel}>Estimated Time:</span>
            <span className={styles.infoValue}>10 mins</span>
          </div>
          <div className={styles.infoItem}>
            <span className={styles.infoLabel}>Prerequisites:</span>
            <span className={styles.infoValue}>None!</span>
          </div>
          <div className={styles.infoItem}>
            <span className={styles.infoLabel}>Last Updated:</span>
            <span className={styles.infoValue}>February 2026</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Navigation;