import styles from './Navigation.module.css';

const Navigation = ({ currentModule, setCurrentModule, totalModules = 6 }) => {
  const modules = [
    { id: 1, title: "Module 1: Arrays and Their Structure" },
    { id: 2, title: "Module 2: Properties of Implicit Trees" },
    { id: 3, title: "Module 3: Memory Efficiency" },
    { id: 4, title: "Module 4: Advanced Operations" },
    { id: 5, title: "Module 5: Generalizing to d-ary Trees" },
    { id: 6, title: "Module 6: Binary Heaps Application" }
  ];

  return (
    <nav className={styles.navigation}>
      <div className={styles.navHeader}>
        <h2>Implicit Trees</h2>
        <div className={styles.progress}>
          <span>Progress: {currentModule}/{totalModules}</span>
          <div className={styles.progressBar}>
            <div 
              className={styles.progressFill} 
              style={{ width: `${(currentModule / totalModules) * 100}%` }}
            />
          </div>
        </div>
      </div>
      
      <ul className={styles.navList}>
        {modules.map(module => (
          <li key={module.id}>
            <button
              className={`${styles.navItem} ${currentModule === module.id ? styles.active : ''}`}
              onClick={() => setCurrentModule(module.id)}
            >
              <span className={styles.moduleNumber}>{module.id.toString().padStart(2, '0')}</span>
              <span className={styles.moduleTitle}>{module.title}</span>
              {currentModule > module.id && (
                <span className={styles.completedIcon}>✓</span>
              )}
            </button>
          </li>
        ))}
      </ul>
      
    </nav>
  );
};

export default Navigation;