import React from 'react';
import styles from './Navigation.module.css';

const Navigation = ({ currentModule, setCurrentModule, totalModules = 6 }) => {
  const modules = [
    { id: 1, title: "Arrays and Their Structure" },
    { id: 2, title: "Properties of Implicit Trees" },
    { id: 3, title: "Memory Efficiency" },
    { id: 4, title: "Advanced Operations" },
    { id: 5, title: "Generalizing to d-ary Trees" },
    { id: 6, title: "Binary Heaps Application" }
  ];

  return (
    <nav className={styles.navigation}>
      <div className={styles.navHeader}>
        <h2 className={styles.courseTitle}>Implicit Trees</h2>
        <div className={styles.courseInfo}>
          <span className={styles.courseMeta}>Data Structures • Intermediate</span>
        </div>
      </div>
      
      <div className={styles.progressSection}>
        <div className={styles.progressHeader}>
          <span className={styles.progressLabel}>Your Progress</span>
          <span className={styles.progressPercent}>{Math.round((currentModule / totalModules) * 100)}%</span>
        </div>
        <div className={styles.progressBar}>
          <div 
            className={styles.progressFill} 
            style={{ width: `${(currentModule / totalModules) * 100}%` }}
          />
        </div>
        <div className={styles.modulesCompleted}>
          {currentModule} of {totalModules} modules completed
        </div>
      </div>
      
      <div className={styles.navContent}>
        <h3 className={styles.sectionTitle}>Course Modules</h3>
        <ul className={styles.moduleList}>
          {modules.map(module => (
            <li key={module.id} className={styles.moduleItem}>
              <button
                className={`${styles.moduleButton} ${currentModule === module.id ? styles.active : ''} ${currentModule > module.id ? styles.completed : ''}`}
                onClick={() => setCurrentModule(module.id)}
              >
                <div className={styles.moduleIndicator}>
                  <span className={styles.moduleNumber}>
                    {currentModule > module.id ? '✓' : module.id}
                  </span>
                </div>
                <div className={styles.moduleDetails}>
                  <span className={styles.moduleTitle}>Module {module.id}</span>
                  <span className={styles.moduleDesc}>{module.title}</span>
                </div>
                <div className={styles.moduleDuration}>2 min</div>
              </button>
            </li>
          ))}
        </ul>

      </div>
    </nav>
  );
};

export default Navigation;