import styles from './ContentModule.module.css';
import TreeDiagram from './TreeDiagram';
import ArrayVisual from './ArrayVisual';
import DaryTreeDiagram from './DaryTreeDiagram';
import HeapVisualization from './HeapVisualization';
import CodeBlock from './CodeBlock';

const ContentModule = ({ moduleData, diagrams }) => {
  const renderSection = (section, index) => {
    switch (section.type) {
      case 'text':
        return <p key={index} className={styles.text}>{section.content}</p>;
      
      case 'visual_comparison':
        return (
          <div key={index} className={styles.visualComparison}>

            <h3>{section.title}</h3>

            <div className={styles.comparisonContainer}>
              <ArrayVisual array={diagrams.module1.array} hasTitle={true} />
              <TreeDiagram array={diagrams.module1.array} />
            </div>

            <p>{section.content}</p>

          </div>
        );
      
      case 'formula':
        return (
          <div key={index} className={styles.formulaBox}>

            <h3>{section.title}</h3>

            <div className={styles.formulas}>
              {section.formulas.map((formula, i) => (
                <div key={i} className={styles.formulaItem}>
                  {formula}
                </div>
              ))}
            </div>

            <p className={styles.example}>{section.example}</p>
            
          </div>
        );
    
      case 'dary_formula':
        return (
          <div key={index} className={styles.formulaBox}>

            <h3>{section.title}</h3>

            <div className={styles.formulas}>
              {section.formulas.map((formula, i) => (
                <div key={i} className={styles.formulaItem}>
                  {formula}
                </div>
              ))}
            </div>

            <p className={styles.example}>{section.example}</p>

          </div>
        );

      case 'dary_visualization':
        return (
          <div key={index} className={styles.visualBox}>

            <h3>{section.title}</h3>

            <DaryTreeDiagram 
              d={section.d || 3}
              array={section.array || diagrams.module5?.ternaryTree?.array || ["A", "B", "C", "D", "E", "F", "G", "H", "I", "J"]}
            />

            {section.content && <p className={styles.visualDescription}>{section.content}</p>}

          </div>
        );

      case 'heap_visualization':
        return (
          <div key={index} className={styles.visualBox}>

            <h3>{section.title}</h3>

            <HeapVisualization 
              heapArray={section.heapArray || diagrams.module6?.heapArray || []}
              operations={section.operations || diagrams.module6?.heapOperations || []}
              interactive={section.interactive || false}
            />

            {section.content && <p className={styles.visualDescription}>{section.content}</p>}

          </div>
        );
      
      case 'practice':
        return (
          <div key={index} className={styles.practiceBox}>

            <h4>Quick Practice</h4>

            <p className={styles.question}>{section.question}</p>

            <div className={styles.options}>
              {section.options.map((option, i) => (
                <div key={i} className={styles.option}>
                  {String.fromCharCode(65 + i)}) {option}
                </div>
              ))}
            </div>

            <div className={styles.explanation}>
              <strong>Answer: </strong>
              {section.explanation}
            </div>

          </div>
        );
      
      case 'code':
        return (
          <div key={index}>

            {section.title && <h3>{section.title}</h3>}

            <CodeBlock 
              code={section.code} 
              language={section.language || 'python'}
            />

          </div>
        );
      
      case 'step_by_step':
        return (
          <div key={index} className={styles.steps}>

            <h3>{section.title}</h3>

            <ol className={styles.stepList}>
              {section.steps.map((step, i) => (
                <li key={i} className={styles.stepItem}>{step}</li>
              ))}
            </ol>

          </div>
        );
      
      case 'bullets':
        return (
          <div key={index} className={styles.bullets}>

            <h3>{section.title}</h3>

            <ul>
              {section.items.map((item, i) => (
                <li key={i}>{item}</li>
              ))}
            </ul>

          </div>
        );
      
      case 'definition':
        return (
          <div key={index} className={styles.definitionBox}>

            <h4>{section.term}</h4>

            <p className={styles.definition}>{section.definition}</p>

          </div>
        );
      
      case 'visual':
        return (
          <div key={index} className={styles.visualBox}>

            <h3>{section.title}</h3>

            <p className={styles.visualContent}>{section.content}</p>

          </div>
        );
      
      case 'comparison':
        return (
          <div key={index} className={styles.comparisonBox}>

            <h3>{section.title}</h3>

            <div className={styles.comparisonGood}>
              <strong>✓:</strong> {section.good}
            </div>

            <div className={styles.comparisonBad}>
              <strong>✗:</strong> {section.bad}
            </div>

          </div>
        );
      
      default:
        return null;
    }
  };

  return (
    <div className={styles.contentModule}>

      <h2 className={styles.moduleTitle}>{moduleData.title}</h2>

      {moduleData.sections.map((section, index) => renderSection(section, index))}
      
    </div>
  );
};

export default ContentModule;