import styles from './Tree.module.css';

const Tree = ({ treeData, width = 500, height = 300 }) => {
  const renderTree = (node, x, y, level) => {
    if (!node) return null;
    
    const horizontalSpacing = 100 / (level * 0.7 + 1);
    const verticalSpacing = 70;
    const elements = [];
    
    // current node
    elements.push(
      <g key={`node-${node.index}`}>
        <circle cx={x} cy={y} r="18" className={styles.nodeCircle} />
        <text x={x} y={y} textAnchor="middle" dy=".3em" className={styles.nodeText}>
          {node.value}
        </text>
        <text x={x} y={y + 25} textAnchor="middle" dy=".5em" className={styles.indexText}>
          ({node.index})
        </text>
      </g>
    );
    
    // children
    const children = node.children || [];
    const childCount = children.length;
    
    if (childCount > 0) {
      const totalWidth = childCount * horizontalSpacing;
      const startX = x - totalWidth/2 + horizontalSpacing/2;
      
      children.forEach((child, index) => {
        if (!child) return;
        
        const childX = startX + index * horizontalSpacing;
        const childY = y + verticalSpacing;
        
        // edge
        elements.push(
          <line 
            key={`line-${child.index}`}
            x1={x} y1={y + 18}
            x2={childX} y2={childY - 18}
            className={styles.treeEdge}
          />
        );
        
        // recursive child
        elements.push(...renderTree(child, childX, childY, level + 1));
      });
    }
    
    return elements;
  };
  
  const svgHeight = height;
  const rootX = width / 2;
  const rootY = 50;
  
  return (
    <div className={styles.treeContainer}>
      <svg 
        width="100%" 
        height={svgHeight} 
        className={styles.treeSvg}
        viewBox={`0 0 ${width} ${svgHeight}`}
        preserveAspectRatio="xMidYMid meet"
      >
        {treeData && renderTree(treeData, rootX, rootY, 0)}
      </svg>
    </div>
  );
};

export default Tree;