import Tree from '../tree-visuals/Tree';
import { buildBinaryTree, getSpacingFunction } from '../tree-visuals/treeBuilders';
import styles from './TreeDiagram.module.css';

export const TreeDiagram = ({ array }) => {
  const tree = buildBinaryTree(array);
  
  return (
    <div className={styles.treeContainer}>
      <h4>Tree Representation</h4>
      <Tree 
        treeData={tree}
        width={350}
        height={250}
        verticalSpacing={70}
        horizontalSpacing={120}
        getChildSpacing={getSpacingFunction('binary')}
      />
    </div>
  );
};

export default TreeDiagram;