import React from 'react';
import styles from './ContentHeader.module.css';

const ContentHeader = ({ currentModule, totalModules, onNext, onPrevious }) => {
  const progressPercentage = (currentModule / totalModules) * 100;
  
  return (
    <header className={styles.contentHeader}>
      <div className={styles.headerLeft}>
        <div className={styles.courseInfo}>
          <h1 className={styles.courseTitle}>Implicit Trees</h1>
          <div className={styles.courseMeta}>
            <span className={styles.courseCategory}>Data Structures</span>
            <span className={styles.courseLevel}>• Intermediate</span>
            <span className={styles.courseDuration}>• 6 Modules</span>
          </div>
        </div>
      </div>
      
      <div className={styles.headerCenter}>
        <div className={styles.progressSection}>
          <div className={styles.progressInfo}>
            <span className={styles.progressLabel}>Progress</span>
            <span className={styles.progressPercent}>{Math.round(progressPercentage)}%</span>
          </div>
          <div className={styles.progressBar}>
            <div 
              className={styles.progressFill} 
              style={{ width: `${progressPercentage}%` }}
            />
          </div>
        </div>
      </div>
      
      <div className={styles.headerRight}>
        <div className={styles.navigationControls}>
          <button 
            className={`${styles.navButton} ${styles.prevButton}`}
            onClick={onPrevious}
            disabled={currentModule === 1}
          >
            ← Previous
          </button>
          <button 
            className={`${styles.navButton} ${styles.nextButton}`}
            onClick={onNext}
            disabled={currentModule === totalModules}
          >
            Next →
          </button>
        </div>
        
        <div className={styles.headerActions}>
          <button className={styles.actionButton} title="Bookmark">
            <span className={styles.actionIcon}>🔖</span>
          </button>
          <button className={styles.actionButton} title="Notes">
            <span className={styles.actionIcon}>📝</span>
          </button>
          <button className={styles.actionButton} title="Help">
            <span className={styles.actionIcon}>❓</span>
          </button>
        </div>
      </div>
    </header>
  );
};

export default ContentHeader;