import { useState, useEffect, useRef } from 'react';
import { modules, diagrams } from '../data/modules';
import ContentModule from '../components/common/ContentModule';
import Layout from '../components/designs/Design1/Layout';
import styles from './Design1.module.css';

const Design1 = () => {
  const [currentModule, setCurrentModule] = useState(1);
  const contentRef = useRef(null);

  const currentModuleData = modules.find(module => module.id === currentModule);

  // scroll to top when module changes
  useEffect(() => {
    if (contentRef.current) {
      contentRef.current.scrollTop = 0;
    }
  }, [currentModule]);

  const handleNextModule = () => {
    if (currentModule < modules.length) {
      setCurrentModule(prev => prev + 1);
    }
  };

  const handlePreviousModule = () => {
    if (currentModule > 1) {
      setCurrentModule(prev => prev - 1);
    }
  };

  return (
    <div className={styles.design1Container}>
      <Layout 
        currentModule={currentModule} 
        setCurrentModule={setCurrentModule}
        totalModules={modules.length}
      >
        <div className={styles.moduleContent} ref={contentRef}> 
          {currentModuleData && (
            <ContentModule 
              moduleData={currentModuleData} 
              diagrams={diagrams}
            />
          )}
          
          <div className={styles.moduleNavigation}>
            <button 
              className={`${styles.navButton} ${styles.prevButton}`}
              onClick={handlePreviousModule}
              disabled={currentModule === 1}
            >
              ← Previous Module
            </button>
            
            <div className={styles.moduleIndicator}>
              <span className={styles.moduleNumber}>{currentModule}</span>
              <span className={styles.moduleTotal}> of {modules.length}</span>
            </div>
            
            <button 
              className={`${styles.navButton} ${styles.nextButton}`}
              onClick={handleNextModule}
              disabled={currentModule === modules.length}
            >
              Next Module →
            </button>
          </div>
        </div>
      </Layout>
    </div>
  );
};

export default Design1;