import React, { useState, useEffect, useRef } from 'react';
import { slideModules, slideDiagrams } from '../data/slideModules';
import Slide from '../components/designs/Design5/Slide';
import SlideNavigation from '../components/designs/Design5/SlideNavigation';
import ModuleModal from '../components/designs/Design5/ModuleModal';
import styles from './Design5.module.css';

const Design5 = () => {
  const [currentModule, setCurrentModule] = useState(1);
  const [currentSlide, setCurrentSlide] = useState(1);
  const [showModuleModal, setShowModuleModal] = useState(false);
  const contentRef = useRef(null); // Add ref

  const currentModuleData = slideModules.find(m => m.id === currentModule);
  const currentSlideData = currentModuleData?.slides.find(s => s.id === currentSlide);
  const totalSlides = currentModuleData?.slides.length || 0;
  
  /* reset to first slide when module changes
  useEffect(() => {
    setCurrentSlide(1);
  }, [currentModule]);*/

  // scroll to top when module changes
  useEffect(() => {
    if (contentRef.current) {
      contentRef.current.scrollTop = 0;
    }
  }, [currentSlide]);

  const handleNextSlide = () => {
    if (currentSlide < totalSlides) {
      setCurrentSlide(prev => prev + 1);
    } else if (currentModule < slideModules.length) {
      // move to next module
      setCurrentModule(prev => prev + 1);
      setCurrentSlide(1);
    }
  };

  const handlePreviousSlide = () => {
    if (currentSlide > 1) {
      setCurrentSlide(prev => prev - 1);
    } else if (currentModule > 1) {
      // move to previous module
      const prevModule = slideModules.find(m => m.id === currentModule - 1);
      setCurrentModule(prev => prev - 1);
      setCurrentSlide(prevModule?.slides.length || 1);
    }
  };

  const handleSelectModule = (moduleId) => {
    setCurrentModule(moduleId);
    setShowModuleModal(false);
  };

  const handleModuleSelectClick = () => {
    setShowModuleModal(true);
  };

  return (
    <div className={styles.design5Container}>
      
      <div className={styles.moduleHeader}>
        <div className={styles.moduleInfo}>
          <span className={styles.moduleNumber}>Module {currentModule}</span>
          <h1 className={styles.moduleTitle}>{currentModuleData?.title}</h1>
        </div>
        <button 
          className={styles.menuButton}
          onClick={handleModuleSelectClick}
        >
          ☰ Menu
        </button>
      </div>

      
      <div className={styles.slideContainer}>
        {currentSlideData && (
          <Slide slide={currentSlideData} diagrams={slideDiagrams} scrollRef={contentRef} />
        )}
      </div>

      
      <SlideNavigation 
        currentSlide={currentSlide}
        totalSlides={totalSlides}
        currentModule={currentModule}
        totalModules={6}
        onNext={handleNextSlide}
        onPrevious={handlePreviousSlide}
        onModuleSelect={handleModuleSelectClick}
      />

      
      {showModuleModal && (
        <ModuleModal 
          modules={slideModules}
          currentModuleId={currentModule}
          onSelectModule={handleSelectModule}
          onClose={() => setShowModuleModal(false)}
        />
      )}
    </div>
  );
};

export default Design5;